export async function main(ns) {
  ns.disableLog("sleep");

  if (!ns.stock || (
    typeof ns.stock.buyStock !== "function" &&
    typeof ns.stock.purchaseTixApi !== "function" &&
    typeof ns.stock.hasTixApiAccess !== "function"
  )) {
