        if (isFinite(cost) && cost > 0) {
          const newLevel = level + 1;
          const estNewProd = curProd * (newLevel / Math.max(1, level));
          const delta = Math.max(0, estNewProd - curProd);
          actions.push({ type: "level", index: i, cost, delta, desc: `Node ${i} level+1` });
