      .map(a => ({ ...a, roi: a.cost > 0 ? (a.delta / a.cost) : 0 }))
      .sort((a, b) => b.roi - a.roi);

    // Output top options
   // ns.tprint("🔎 Top hacknet options (estimated Δprod / $):");
