    //  ns.tprint(`❌ Not enough money for the best action. Required ${Math.floor(best.cost).toLocaleString()}, available ${Math.floor(availableCash).toLocaleString()}.`);
      // Wait and retry later
      await ns.sleep(loopDelayMs);
      continue;
