export const GYM_BASE_COST = 120;

export const UNIVERSITY_LOCATIONS = [
  { city: "Volhaven", name: "ZB Institute of Technology", expMult: 4, costMult: 5 },
  { city: "Aevum", name: "Summit University", expMult: 3, costMult: 4 },
