export const GYM_LOCATIONS = [
  { city: "Sector-12", name: "Powerhouse Gym", expMult: 10, costMult: 20 },
  { city: "Aevum", name: "Snap Fitness Gym", expMult: 5, costMult: 10 },
  { city: "Volhaven", name: "Millenium Fitness Gym", expMult: 4, costMult: 7 },
