  ns.tprint("╠══════════════════════════════════════════════════════════════════════╣");
  for (let i = 0; i < servers.length; i++) {
    const s = servers[i];
    const root = s.hasRoot ? " " : "🔒";
    const num  = String(i + 1).padEnd(3);
    const name = s.name.length > 18 ? s.name.slice(0, 18) : s.name.padEnd(18);
