    const lvl   = String(s.reqLevel).padStart(4);
    ns.tprint(`║ ${root} ${num} ${name} ${money} ${cur} ${rate} ${lvl}  ║`);
  }
  ns.tprint("╚══════════════════════════════════════════════════════════════════════╝");
  ns.tprint(`  ${servers.length} servers found.`);
